# Let me look at the entire JSON file structure to see if there's any additional yield data
import json

with open('/app/resources/treasury_bulletin_2003_03.json', 'r') as f:
    data = json.load(f)

# Check all keys in the data
def explore(obj, indent=0):
    if isinstance(obj, dict):
        for k, v in obj.items():
            print("  " * indent + str(k))
            if isinstance(v, (dict, list)) and indent < 2:
                explore(v, indent + 1)
    elif isinstance(obj, list) and len(obj) < 10 and indent < 2:
        for item in obj[:3]:
            explore(item, indent + 1)

print("Top level keys:")
for k in data.keys():
    print(f"  {k}")

print("\nDocument structure:")
explore(data['document'])
EOF
